dt egy javaslatot\/aj\u00e1nlatot (pl. They had to reject the _______ due to lack of funds.)<\/p><p>\ud83d\udc49 business _______ = \u00fczleti aj\u00e1nlat (pl. We received several business _______s for the contract.)<\/p><p>\ud83d\udc49 marriage _______ = h\u00e1zass\u00e1gi aj\u00e1nlat (pl. He planned a surprise marriage _______ during their vacation.)<\/p>","front_notes":null,"front_speak":null,"back":"<p><strong>proposal<\/strong><\/p><p>noun: <strong>proposal<\/strong><\/p><p>verb: <strong>propose<\/strong><\/p><p><span style=\"color: #3b82f6\">common pair: make a proposal \/ accept a proposal \/ reject a proposal \/ business proposal<\/span><\/p><p>similar: suggestion \/ offer \/ plan \/ proposition<\/p><p><span style=\"color: #ef4444\">negative: rejection \/ refusal \/ withdrawal<\/span><\/p>","back_notes":null,"back_speak":"proposal","study_direction":"front_to_back","color":"#6366f1","review":{"state":"review","interval":2,"ease_factor":250,"repetitions":1,"lapses":0,"learning_step":0,"is_leech":false,"introduced_on":"2026-06-04","reviewed_on":"2026-06-08","due_at":"2026-06-10T07:51:54+00:00","previous_state":{"state":"learning","due_at":"2026-06-07T20:17:49+00:00","interval":0,"ease_factor":250,"repetitions":0,"lapses":0,"learning_step":3,"is_leech":false,"introduced_on":"2026-06-04","reviewed_on":"2026-06-07"}},"previews":{"again":"1 perc (\u2192 1 nap)","hard":"3 nap","good":"4 nap","easy":"5 nap"},"other_side_due_at":"2026-06-10T07:46:07+00:00"}]},"url":"\/flashcards\/38\/study","version":"4c93d35e7a64fa8ace8681d8dca9c213","sharedProps":["errors","name","auth","sidebarOpen","flash"]}</script><div id="app"></div><?php /**PATH /var/www/clients/client982/web3567/web/topwords.eu/storage/framework/views/04446dd702a5bd40944a92c7d1044ef7.blade.php ENDPATH**/ ?>